<script setup>
import {computed,onMounted,onUnmounted,ref} from 'vue';
import BiofilmPorphyrinQlfScanner from './components/BiofilmPorphyrinQlfScanner.vue';
import TmjVibroarthrometryLab from './components/TmjVibroarthrometryLab.vue';
import StephanCurveEnamelKinetics from './components/StephanCurveEnamelKinetics.vue';
import VitaToothShadeColorimeter from './components/VitaToothShadeColorimeter.vue';
import SonicBrushForceCdtAuditor from './components/SonicBrushForceCdtAuditor.vue';
import HardwarePermissionGatekeeper from './components/HardwarePermissionGatekeeper.vue';
import PolyglotRuntimeInspectorModal from './components/PolyglotRuntimeInspectorModal.vue';
import ApkReleaseDownloadModal from './components/ApkReleaseDownloadModal.vue';
import EnamelShaderBackground from './components/EnamelShaderBackground.vue';
import RecordHistoryModal from './components/RecordHistoryModal.vue';
import {saveRecord,queueCount,exportVault} from './db/dentaVaultDb.js';
const active=ref('biofilm');const theme=ref(localStorage.getItem('denta-theme')||'obsidian');const role=ref(localStorage.getItem('denta-role')||'Patient');const modal=ref('');const queued=ref(0);const notice=ref('');const online=ref(navigator.onLine);const viewport=ref('desktop');const saving=ref(false);const sensorStatus=ref({camera:'Not requested',mic:'Not requested',motion:'Simulator'});
const tabs=[{id:'biofilm',icon:'◉',label:'Biofilm scan',component:BiofilmPorphyrinQlfScanner},{id:'tmj',icon:'⌁',label:'TMJ lab',component:TmjVibroarthrometryLab},{id:'stephan',icon:'∿',label:'Stephan curve',component:StephanCurveEnamelKinetics},{id:'shade',icon:'◈',label:'Shade lab',component:VitaToothShadeColorimeter},{id:'brush',icon:'↗',label:'Brush & quotes',component:SonicBrushForceCdtAuditor}];
const current=computed(()=>tabs.find(x=>x.id===active.value)?.component);
const themeClass=computed(()=>`theme-${theme.value}`);
const setTheme=value=>{theme.value=value;localStorage.setItem('denta-theme',value)};
const setRole=value=>{role.value=value;localStorage.setItem('denta-role',value);modal.value=value==='Systems architect'?'inspector':''};
const onSave=async payload=>{saving.value=true;try{const {module,...record}=payload;await saveRecord(module,record);queued.value=await queueCount();notice.value='Saved locally · queued for sync when a backend is configured.';setTimeout(()=>notice.value='',3600)}catch{notice.value='Could not save this record on this device.'}finally{saving.value=false}};
const refreshQueue=async()=>{queued.value=await queueCount()};const exportData=async()=>{const blob=new Blob([JSON.stringify(await exportVault(),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='denta-spectra-local-export.json';a.click();URL.revokeObjectURL(url)};
const updateNetwork=()=>online.value=navigator.onLine;const changeTheme=e=>setTheme(e.target.value);const applyDeviceTilt=e=>{document.documentElement.style.setProperty('--tilt-x',`${Math.max(-12,Math.min(12,(e.gamma||0)/3))}deg`)};
onMounted(()=>{refreshQueue();window.addEventListener('online',updateNetwork);window.addEventListener('offline',updateNetwork);window.addEventListener('deviceorientation',applyDeviceTilt)});onUnmounted(()=>{window.removeEventListener('online',updateNetwork);window.removeEventListener('offline',updateNetwork);window.removeEventListener('deviceorientation',applyDeviceTilt)});
</script>
<template><main class="shell" :class="themeClass"><EnamelShaderBackground/><div class="ambient"></div><div class="grain"></div><div class="app-frame" :class="{pushed:!!modal,'phone-preview':viewport==='mobile'}" :style="viewport==='mobile'?{maxWidth:'440px'}:{}"><header class="topbar"><div class="brand"><div class="brand-mark">✳</div><div><div class="brand-title">DENTA SPECTRA</div><div class="brand-caption">Oral health · insight workspace</div></div></div><div class="top-actions"><span class="status-chip"><i class="dot" :style="{background:online?'#59dfb5':'#e6ac51'}"></i>{{online?'LOCAL · ONLINE':'OFFLINE READY'}}</span><select class="pill hide-mobile" :value="theme" @change="changeTheme" aria-label="Theme"><option value="obsidian">Obsidian</option><option value="daylight">Daylight</option><option value="qlf">405 nm view</option><option value="eco">Eco glass</option></select><button class="pill hide-mobile" @click="modal='role'">{{role}} ▾</button><button class="pill" @click="modal='apk'">↓ APK</button></div></header><section class="hero"><div><div class="eyebrow">Preventive dentistry · daily build 22</div><h1>See your oral health<br><span class="headline-accent">from a new angle.</span></h1><p>A private, offline-ready workspace for learning about oral biofilm signals, jaw-motion patterns, enamel pH models, tooth shade, and brushing habits.</p></div><div class="status-chip"><i class="dot"></i> Five interactive labs · no sign-in</div></section><div class="layout"><section class="main-column"><nav class="tabs" aria-label="Dental modules"><button v-for="tab in tabs" :key="tab.id" class="tab" :class="{active:active===tab.id}" @click="active=tab.id"><span class="tab-icon">{{tab.icon}}</span>{{tab.label}}</button></nav><component :is="current" :key="active" @save="onSave"/><div v-if="notice" class="toast">{{notice}}</div><div class="safety-line">Educational estimates only · not a diagnosis, treatment recommendation, calibrated measurement, or substitute for a dental professional.</div></section><aside class="sidebar"><div class="side-card glass"><div class="side-title"><span>Quick view</span><span class="eyebrow">TODAY</span></div><div class="risk"><strong>Small steps count</strong><p>Brush twice daily with fluoride toothpaste, clean between teeth, and book routine dental checkups.</p></div><div class="metric-grid" style="grid-template-columns:1fr 1fr"><div class="metric"><span>Local records</span><b>{{queued}}</b></div><div class="metric"><span>Connection</span><b style="font-size:12px">{{online?'Online':'Offline'}}</b></div></div><button class="action secondary" style="width:100%" @click="exportData">Export my records</button></div><div class="side-card glass"><div class="side-title"><span>Sensor status</span><button class="action secondary" @click="modal='hardware'">Manage</button></div><div class="control-row"><span class="small">Camera</span><span class="badge">{{sensorStatus.camera.toUpperCase()}}</span></div><div class="control-row"><span class="small">Microphone</span><span class="badge">{{sensorStatus.mic.toUpperCase()}}</span></div><div class="control-row"><span class="small">Motion</span><span class="badge">{{sensorStatus.motion.toUpperCase()}}</span></div><p class="footnote">Camera, audio and motion access are optional and requested only by the user.</p></div><div class="side-card glass"><div class="side-title"><span>Offline vault</span><span class="eyebrow">LOCAL</span></div><p class="small">Records are stored on this device. No account or cloud sync is configured in this demo.</p><div class="split"><button class="action secondary" @click="modal='history'">View records</button><button class="action secondary" @click="exportData">Export JSON</button></div></div><div class="side-card glass"><div class="side-title"><span>Device preview</span></div><div class="split"><button class="action secondary" :class="{active:viewport==='desktop'}" @click="viewport='desktop'">Desktop</button><button class="action secondary" :class="{active:viewport==='mobile'}" @click="viewport='mobile'">Mobile frame</button></div></div></aside></div><footer class="footer">Denta Spectra · v1.22.0 · This project is for education and personal tracking only. Camera-based color values are affected by lighting, device optics, and display settings. Contact a dental professional for diagnosis or care.</footer></div><nav class="nav-dock" aria-label="Quick module navigation"><button v-for="tab in tabs" :key="tab.id" :class="{active:active===tab.id}" @click="active=tab.id">{{tab.icon}} <span>{{tab.label.split(' ')[0]}}</span></button></nav><component :is="modal==='hardware'?HardwarePermissionGatekeeper:modal==='inspector'?PolyglotRuntimeInspectorModal:modal==='apk'?ApkReleaseDownloadModal:modal==='history'?RecordHistoryModal:null" v-if="['hardware','inspector','apk','history'].includes(modal)" @close="modal=''" @status="sensorStatus=$event"/><div v-if="modal==='role'" class="modal-backdrop" @click.self="modal=''"><section class="modal glass"><div class="modal-head"><div><div class="eyebrow">Personalized view</div><h2>Choose a workspace role</h2><p class="small">This is a local display preference, not identity verification or access control.</p></div><button class="close" @click="modal=''">×</button></div><div class="role-list"><button v-for="item in [{name:'Patient',caption:'Self-care and examples'},{name:'Dentist',caption:'Clinical visualization preview'},{name:'Systems architect',caption:'Polyglot implementation details'}]" :key="item.name" class="role" :class="{selected:role===item.name}" @click="setRole(item.name)"><b>{{item.name}}</b><div class="small">{{item.caption}}</div></button></div><button v-if="role==='Systems architect'" class="action" style="margin-top:14px" @click="modal='inspector'">Open runtime inspector</button></section></div></main></template>
<style scoped>.headline-accent{color:#8bead4}.safety-line{font-size:9px;color:#7c8b92;padding:13px 5px;line-height:1.6}.toast{position:fixed;bottom:92px;left:50%;transform:translateX(-50%);padding:12px 18px;background:#0e2c2a;border:1px solid #70dfca55;border-radius:12px;color:#c7fff1;font-size:11px;z-index:15;box-shadow:0 14px 40px #0008}.theme-daylight .headline-accent{color:#188b78}</style>
